    output logic [7:0]                              m_axil_mon_wstrb,
    input  logic                                    m_axil_mon_bvalid,
    output logic                                    m_axil_mon_bready,
    input  logic [1:0]                              m_axil_mon_bresp,

    // Interrupt output
    output logic                                    mon_irq,

    // Configuration: the trace window and the error window (inclusive bounds;
    // the error writer wraps to its base past the last whole record)
    input  logic [31:0]                             cfg_mon_base_addr,
    input  logic [31:0]                             cfg_mon_limit_addr,
    input  logic [15:0]                             cfg_mon_flush_watermark,
    input  logic [31:0]                             cfg_mon_err_base_addr,
    input  logic [31:0]                             cfg_mon_err_limit_addr,
    input  logic [15:0]                             cfg_mon_err_flush_watermark,  // beats; 3 = every record
    output logic [15:0]                             mon_err_rec_count,            // whole error records landed, free-running

    //-------------------------------------------------------------------------
    // Status (per-half top-level observation)
    //-------------------------------------------------------------------------
    output logic                                    src_system_idle,
    output logic [NC-1:0]                           src_sched_error,
    output logic                                    snk_system_idle,
    output logic [NC-1:0]                           snk_sched_error,

    //-------------------------------------------------------------------------
    // Tile header status (sink port; constant 0 unless TILE_HDR)
    //-------------------------------------------------------------------------
    output logic                                    sts_tile_unsupported,    // sticky
    output logic                                    sts_tile_tag_mismatch,   // sticky
    output logic [15:0]                             sts_tile_desc_count,
    output logic [15:0]                             sts_tile_credit_count,
    output logic [NC-1:0]                           sts_tile_desc_dropped,   // sticky per source channel

    //-------------------------------------------------------------------------
    // Straps toward RAPIDS (TILE_CREDITS; idle 0 otherwise): credit returns
    // to the cells and cores on their own interface, one header-only credit
    // packet (the 128-bit tile header) per transfer; and the tile's global
    // quiescent signal, which gates a resync (SRC.TILE_RESYNC) and every
    // channel reset of either half
    //-------------------------------------------------------------------------
    output logic                                    m_tile_credit_valid,
    input  logic                                    m_tile_credit_ready,
    output logic [127:0]                            m_tile_credit_data,
    input  logic                                    tile_quiescent
);

    // Boundary reset synchronization. The port aresetn is treated as an
    // asynchronous-assert input of unknown deassert quality; an N=3
    // reset_sync (rtl/cdc, formally proven) produces the internal reset
    // every block below sees.
    logic w_aresetn;
    reset_sync #(
        .N             (3),
        .KEEP_ATTRS    (1'b1),
        .IN_ACTIVE_LOW (1'b1),
        .OUT_ACTIVE_LOW(1'b1),
        .ASYNC_ASSERT  (1'b1)
    ) u_reset_sync (
        .clk        (aclk),
        .rst_n      (aresetn),
        .sync_rst_n (w_aresetn)
    );

    //=========================================================================
    // APB -> CMD/RSP (single clock domain)
    //=========================================================================
    logic                          apb_cmd_valid;
    logic                          apb_cmd_ready;
    logic                          apb_cmd_pwrite;
    logic [APB_ADDR_WIDTH-1:0]     apb_cmd_paddr;
    logic [APB_DATA_WIDTH-1:0]     apb_cmd_pwdata;
    logic [(APB_DATA_WIDTH/8)-1:0] apb_cmd_pstrb;
    logic                          apb_rsp_valid;
    logic                          apb_rsp_ready;
    logic [APB_DATA_WIDTH-1:0]     apb_rsp_prdata;
    logic                          apb_rsp_pslverr;

    apb4_slave #(
        .ADDR_WIDTH (APB_ADDR_WIDTH),
        .DATA_WIDTH (APB_DATA_WIDTH)
    ) u_apb4_slave (
        .pclk           (aclk),
        .presetn        (w_aresetn),
        .s_apb_PSEL     (s_apb_psel),
        .s_apb_PENABLE  (s_apb_penable),
        .s_apb_PREADY   (s_apb_pready),
        .s_apb_PADDR    (s_apb_paddr),
        .s_apb_PWRITE   (s_apb_pwrite),
        .s_apb_PWDATA   (s_apb_pwdata),
        .s_apb_PSTRB    (s_apb_pstrb),
        .s_apb_PPROT    (3'b000),
        .s_apb_PRDATA   (s_apb_prdata),
        .s_apb_PSLVERR  (s_apb_pslverr),
        .cmd_valid      (host_cmd_valid),
        .cmd_ready      (host_cmd_ready),
        .cmd_pwrite     (host_cmd_pwrite),
        .cmd_paddr      (host_cmd_paddr),
        .cmd_pwdata     (host_cmd_pwdata),
        .cmd_pstrb      (apb_cmd_pstrb),
        .cmd_pprot      (),
        .rsp_valid      (host_rsp_valid),
        .rsp_ready      (host_rsp_ready),
        .rsp_prdata     (host_rsp_prdata),
        .rsp_pslverr    (host_rsp_pslverr)
    );

`include "rapids_g_top_reg_arb.svh"

    //=========================================================================
    // APB -> register chain (single sink)
    //=========================================================================
    // This used to be a 3-way demux: 0x000-0x03F and 0x1000-0x103F were carved
    // out as kick windows and everything else went to the register
    // chain. Those windows are now ordinary registers (CHx_DESC_ADDR_{LOW,HIGH}
    // and KICK_ENABLE at the same offsets), so every access goes to the
    // register block and the demux is gone.
    //=========================================================================
    logic                          peakrdl_cmd_valid;
    logic                          peakrdl_cmd_ready;
    logic                          peakrdl_rsp_valid;
    logic                          peakrdl_rsp_ready;
    logic [APB_DATA_WIDTH-1:0]     peakrdl_rsp_prdata;
    logic                          peakrdl_rsp_pslverr;

    // MON-window guard (rapids ISSUE-003, the STREAM TASK-002 shape). With
    // USE_MON_REGS=0 the monitor registers configure nothing -- both config
    // blocks strap their cfg_*mon_* outputs off -- so answering them normally
    // would let a host arm a monitor register, read the written value back and
    // conclude a monitor is configured that does not exist. The two windows
    // (SRC MON at 0x0800-0x0FFF, SNK MON at 0x1800-0x1FFF: paddr[11] set in
    // either 4 KB half) return an error response instead. It cannot live in the
    // regblock: generated rapids_regs ties cpuif_wr_err to '0.
    //
    // Decode is combinational, the selection is registered when the command is
    // accepted and cleared when the response is accepted, and the response is
    // muxed on the REGISTERED select. Safe because apb4_slave is strictly
    // one-outstanding. With USE_MON_REGS=1 (the default) w_mon_blocked is a
    // constant 0 and this folds to the straight-through wiring it replaces.
    localparam int MON_WINDOW_BIT = 11;

    logic w_mon_blocked;
    logic r_mon_err_pending;

    generate
        if (APB_ADDR_WIDTH > MON_WINDOW_BIT) begin : g_mon_guard
            assign w_mon_blocked = !USE_MON_REGS && apb_cmd_paddr[MON_WINDOW_BIT];
        end else begin : g_no_mon_window
            assign w_mon_blocked = 1'b0;   // bus too narrow to reach a MON window
        end
    endgenerate

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_mon_err_pending <= 1'b0;
        end else if (apb_cmd_valid && apb_cmd_ready && w_mon_blocked) begin
            r_mon_err_pending <= 1'b1;
        end else if (apb_rsp_valid && apb_rsp_ready) begin
            r_mon_err_pending <= 1'b0;
        end
    )

    // A blocked access never reaches the adapter but is still ACCEPTED: APB
    // cannot express "ignored", and holding cmd_ready low would hang the bus.
    assign peakrdl_cmd_valid = apb_cmd_valid && !w_mon_blocked;
    assign apb_cmd_ready     = w_mon_blocked ? !r_mon_err_pending : peakrdl_cmd_ready;
    // The guard's error beat wins while pending; the adapter is held off so it
    // cannot double-respond.
    assign apb_rsp_valid     = r_mon_err_pending ? 1'b1 : peakrdl_rsp_valid;
    assign peakrdl_rsp_ready = !r_mon_err_pending && apb_rsp_ready;
    assign apb_rsp_prdata    = r_mon_err_pending ? '0   : peakrdl_rsp_prdata;
    assign apb_rsp_pslverr   = r_mon_err_pending ? 1'b1 : peakrdl_rsp_pslverr;

    //=========================================================================
    // SOURCE channel descriptor requests (driven from the staged
    // CHx_DESC_ADDR pair + KICK_ENABLE, below the register block)
    //=========================================================================
    logic [NC-1:0]          src_apb_valid;
    logic [NC-1:0]          src_apb_ready;
    logic [NC-1:0][AW-1:0]  src_apb_addr;


    //=========================================================================
    // SINK channel descriptor requests (same source, below)
    //=========================================================================
    logic [NC-1:0]          snk_apb_valid;
    logic [NC-1:0]          snk_apb_ready;
    logic [NC-1:0][AW-1:0]  snk_apb_addr;


    //=========================================================================
    // PeakRDL passthrough adapter (peakrdl_to_cmdrsp)
    //=========================================================================
    logic                          regblk_req;
    logic                          regblk_req_is_wr;
    logic [APB_ADDR_WIDTH-1:0]     regblk_addr;
    logic [APB_DATA_WIDTH-1:0]     regblk_wr_data;
    logic [APB_DATA_WIDTH-1:0]     regblk_wr_biten;
    logic                          regblk_req_stall_wr;
    logic                          regblk_req_stall_rd;
    logic                          regblk_rd_ack;
    logic                          regblk_rd_err;
    logic [APB_DATA_WIDTH-1:0]     regblk_rd_data;
    logic                          regblk_wr_ack;
    logic                          regblk_wr_err;

    peakrdl_to_cmdrsp #(
        .ADDR_WIDTH (APB_ADDR_WIDTH),
        .DATA_WIDTH (APB_DATA_WIDTH)
    ) u_peakrdl_adapter (
        .aclk               (aclk),
        .aresetn            (w_aresetn),
        .cmd_valid          (peakrdl_cmd_valid),
        .cmd_ready          (peakrdl_cmd_ready),
        .cmd_pwrite         (apb_cmd_pwrite),
        .cmd_paddr          (apb_cmd_paddr),
        .cmd_pwdata         (apb_cmd_pwdata),
        .cmd_pstrb          ({(APB_DATA_WIDTH/8){1'b1}}),
        .rsp_valid          (peakrdl_rsp_valid),
        .rsp_ready          (peakrdl_rsp_ready),
        .rsp_prdata         (peakrdl_rsp_prdata),
        .rsp_pslverr        (peakrdl_rsp_pslverr),
        .regblk_req         (regblk_req),
        .regblk_req_is_wr   (regblk_req_is_wr),
        .regblk_addr        (regblk_addr),
        .regblk_wr_data     (regblk_wr_data),
        .regblk_wr_biten    (regblk_wr_biten),
        .regblk_req_stall_wr(regblk_req_stall_wr),
        .regblk_req_stall_rd(regblk_req_stall_rd),
        .regblk_rd_ack      (regblk_rd_ack),
        .regblk_rd_err      (regblk_rd_err),
        .regblk_rd_data     (regblk_rd_data),
        .regblk_wr_ack      (regblk_wr_ack),
        .regblk_wr_err      (regblk_wr_err)
    );

    //=========================================================================
    // PeakRDL Register Block (`RAPIDS_REGS_MOD: rapids_regs or rapids_regs_16ch)
    // - split SRC / SNK
    //=========================================================================
    initial begin
        if (NC > `RAPIDS_REGS_NCH)
            $fatal(1, "NUM_CHANNELS (%0d) exceeds the %0d-channel register map in this build",
                   NC, `RAPIDS_REGS_NCH);
    end

    // Core status collected for register read-back (driven into hwif_in
    // below). These pins were dangling at the core instantiation, so the
    // status they carry had nowhere to go.
    logic [NC-1:0]       src_desc_engine_idle, snk_desc_engine_idle;
    logic [NC-1:0]       src_sched_idle,       snk_sched_idle;
    logic [NC-1:0][6:0]  src_sched_state,      snk_sched_state;
    logic [NC-1:0]       src_rd_all_complete;

    `RAPIDS_REGS_IN_T  hwif_in;
    `RAPIDS_REGS_OUT_T hwif_out;


    //=========================================================================
    // Descriptor-monitor perf window: run control down, counters up.
    // Declared here rather than beside their cfg_* namesakes because the
    // read-back block below consumes them, and this file is checked for
    // declaration-before-use.
    //=========================================================================
    logic           src_cfg_desc_mon_perf_run;
    logic           src_sts_desc_mon_win_active;
    logic [31:0]    src_sts_desc_mon_win_cycles;
    logic [31:0]    src_sts_desc_mon_prod_cycles;
    logic [31:0]    src_sts_desc_mon_bp_cycles;
    logic [31:0]    src_sts_desc_mon_starv_cycles;
    logic [31:0]    src_sts_desc_mon_idle_cycles;
    logic [31:0]    src_sts_desc_mon_beat_count;
    logic [63:0]    src_sts_desc_mon_byte_count;
    logic [31:0]    src_sts_desc_mon_burst_count;
    logic           snk_cfg_desc_mon_perf_run;
    logic           snk_sts_desc_mon_win_active;
    logic [31:0]    snk_sts_desc_mon_win_cycles;
    logic [31:0]    snk_sts_desc_mon_prod_cycles;
    logic [31:0]    snk_sts_desc_mon_bp_cycles;
    logic [31:0]    snk_sts_desc_mon_starv_cycles;
    logic [31:0]    snk_sts_desc_mon_idle_cycles;
    logic [31:0]    snk_sts_desc_mon_beat_count;
    logic [63:0]    snk_sts_desc_mon_byte_count;
    logic [31:0]    snk_sts_desc_mon_burst_count;

    //=========================================================================
    // Always-on data-path bus meters (STREAM's axi_bus_meter, RFC Stage E)
    //=========================================================================
    // The RDMON_/WRMON_PERF_* CSRs have existed in the map all along and had
    // no source, so they read 0 in every build. These two meters give them
    // one. They are CHEAP (a few counters each) and deliberately NOT gated by
    // USE_AXI_MONITORS: STREAM's core says the same thing at its own meter
    // ("MUST survive USE_AXI_MONITORS=0") because over-gating them was a real
    // cause of zero perf readings on monitors-off board builds.
    //
    // Halves: rapids_src owns the read master and rapids_snk owns
    // the write master, so read statistics belong to SRC.MON.RDMON_* and
    // write statistics to SNK.MON.WRMON_*.
    //
    // Window control is each half's own CTRL.RUN bit: freeze while RUN is
    // low, and clear on its rising edge, so software opens a window, runs a
    // workload and closes it.
    localparam int MCW = (NC > 1) ? $clog2(NC) : 1;

    logic w_rd_run, w_wr_run, r_rd_run_d, r_wr_run_d;
    assign w_rd_run = hwif_out.SRC.MON.RDMON_PERF_CTRL.RUN.value;
    assign w_wr_run = hwif_out.SNK.MON.WRMON_PERF_CTRL.RUN.value;
    assign src_cfg_desc_mon_perf_run = hwif_out.SRC.MON.DAXMON_PERF_CTRL.RUN.value;
    assign snk_cfg_desc_mon_perf_run = hwif_out.SNK.MON.DAXMON_PERF_CTRL.RUN.value;

    logic [31:0] r_rd_win_cycles, r_wr_win_cycles;
    logic [31:0] r_rd_beats, r_wr_beats;
    logic [63:0] r_rd_bytes, r_wr_bytes;
    logic [31:0] r_rd_bursts, r_wr_bursts;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_rd_run_d      <= 1'b0;
            r_wr_run_d      <= 1'b0;
            r_rd_win_cycles <= '0;
            r_wr_win_cycles <= '0;
            r_rd_beats      <= '0;
            r_wr_beats      <= '0;
            r_rd_bytes      <= '0;
            r_wr_bytes      <= '0;
            r_rd_bursts     <= '0;
            r_wr_bursts     <= '0;
        end else begin
            r_rd_run_d <= w_rd_run;
            r_wr_run_d <= w_wr_run;

            // READ half: clear on the RUN rising edge, accumulate while open.
            if (w_rd_run && !r_rd_run_d) begin
                r_rd_win_cycles <= '0;
                r_rd_beats      <= '0;
                r_rd_bytes      <= '0;
                r_rd_bursts     <= '0;
            end else if (w_rd_run) begin
                r_rd_win_cycles <= r_rd_win_cycles + 32'd1;
                if (m_axi_rd_rvalid && m_axi_rd_rready) begin
                    r_rd_beats <= r_rd_beats + 32'd1;
                    r_rd_bytes <= r_rd_bytes + 64'(DW / 8);
                end
                if (m_axi_rd_arvalid && m_axi_rd_arready) begin
                    r_rd_bursts <= r_rd_bursts + 32'd1;
                end
            end

            // WRITE half: same shape. Bytes come from WSTRB rather than the
            // full beat width, so a partial beat is not counted as a full one.
            if (w_wr_run && !r_wr_run_d) begin
                r_wr_win_cycles <= '0;
                r_wr_beats      <= '0;
                r_wr_bytes      <= '0;
                r_wr_bursts     <= '0;
            end else if (w_wr_run) begin
                r_wr_win_cycles <= r_wr_win_cycles + 32'd1;
                if (m_axi_wr_wvalid && m_axi_wr_wready) begin
                    r_wr_beats <= r_wr_beats + 32'd1;
                    r_wr_bytes <= r_wr_bytes + 64'($countones(m_axi_wr_wstrb));
                end
                if (m_axi_wr_awvalid && m_axi_wr_awready) begin
                    r_wr_bursts <= r_wr_bursts + 32'd1;
                end
            end
        end
    )

    logic [31:0] w_rd_prod, w_rd_bp, w_rd_starv, w_rd_idle;
    logic [31:0] w_wr_prod, w_wr_bp, w_wr_starv, w_wr_idle;

    // Per-channel buckets, presented one channel at a time through
    // <half>.PERF_CH_SEL.CH_SEL (indexed readout, mirroring STREAM's
    // stream_core -> stream_top_ch8 pattern).
    //
    // The WRITE side used to be deliberately unwired: snk_data_path tied
    // off the write engine's o_active_channel_id, so u_wr_bus_meter saw
    // i_channel_id='0 and would have attributed every beat to channel 0 --
    // a fiction, so zeros were reported instead. RAPIDS TASK-001 plumbs that
    // sideband out (engine -> snk_data_path -> ..._axis_beats ->
    // rapids_snk -> rapids_core), so the write buckets are now
    // attributable and WRMON_PERF_CH_* carries real per-channel numbers.
    // The W bus has no wid; axi_bus_meter.sv:71-73 documents exactly this
    // sideband as the intended source.
    logic [15:0] w_rd_ch_prod  [NC];
    logic [15:0] w_rd_ch_bp    [NC];
    logic [15:0] w_rd_ch_starv [NC];
    logic [15:0] w_rd_ch_idle  [NC];
    logic [NC*4-1:0] w_rd_ch_overflow;
    logic [MCW-1:0]  w_rd_ch_sel;
    logic [15:0] w_rd_sel_prod, w_rd_sel_bp, w_rd_sel_starv, w_rd_sel_idle;

    logic [15:0] w_wr_ch_prod  [NC];
    logic [15:0] w_wr_ch_bp    [NC];
    logic [15:0] w_wr_ch_starv [NC];
    logic [15:0] w_wr_ch_idle  [NC];
    logic [NC*4-1:0] w_wr_ch_overflow;
    logic [MCW-1:0]  w_wr_ch_sel;
    logic [15:0] w_wr_sel_prod, w_wr_sel_bp, w_wr_sel_starv, w_wr_sel_idle;

    // Active-channel sideband from the sink write engine (RAPIDS TASK-001).
    logic [CIW-1:0] w_snk_active_ch_id;
    logic           w_snk_active_ch_valid;

    // Slice the 3-bit CSR field to the meter's index width explicitly rather
    // than relying on them happening to match (both are 3 at NC=8).
    assign w_rd_ch_sel = hwif_out.SRC.PERF_CH_SEL.CH_SEL.value[MCW-1:0];
    always_comb begin
        w_rd_sel_prod  = w_rd_ch_prod [w_rd_ch_sel];
        w_rd_sel_bp    = w_rd_ch_bp   [w_rd_ch_sel];
        w_rd_sel_starv = w_rd_ch_starv[w_rd_ch_sel];
        w_rd_sel_idle  = w_rd_ch_idle [w_rd_ch_sel];
    end

    // Write half uses its OWN selector (SNK.PERF_CH_SEL), symmetric with SRC.
    assign w_wr_ch_sel = hwif_out.SNK.PERF_CH_SEL.CH_SEL.value[MCW-1:0];
    always_comb begin
        w_wr_sel_prod  = w_wr_ch_prod [w_wr_ch_sel];
        w_wr_sel_bp    = w_wr_ch_bp   [w_wr_ch_sel];
        w_wr_sel_starv = w_wr_ch_starv[w_wr_ch_sel];
        w_wr_sel_idle  = w_wr_ch_idle [w_wr_ch_sel];
    end
    /* verilator lint_off PINCONNECTEMPTY */
    axi_bus_meter #(.NUM_CHANNELS(NC)) u_rd_bus_meter (
        .aclk               (aclk),
        .aresetn            (w_aresetn),
        .i_clear            (w_rd_run && !r_rd_run_d),
        .i_freeze           (~w_rd_run),
        .i_valid            (m_axi_rd_rvalid),
        .i_ready            (m_axi_rd_rready),
        .i_channel_id       (m_axi_rd_rid[MCW-1:0]),
        .i_channel_valid    (m_axi_rd_rvalid),
        .o_agg_productive   (w_rd_prod),
        .o_agg_backpressure (w_rd_bp),
        .o_agg_starvation   (w_rd_starv),
        .o_agg_idle         (w_rd_idle),
        // Per-channel readout is NOT wired yet. The selector DOES exist --
        // PERF_CH_SEL @ 0x35C, CH_SEL[2:0], sw=rw hw=r in rapids_engine_regs.rdl
        // (an earlier comment here claimed it did not; that was wrong, it looked
        // only at PERF_CONFIG in the MON regfile). The CH_PROD_BP /
        // CH_STARV_IDLE / CH_OVERFLOW registers are sw=r hw=w, so the RDL
        // specifies a contract this module has simply not implemented.
        // STREAM implements it (stream_core.sv u_*_bus_meter ->
        // stream_top_ch8.sv cfg_perf_ch_sel + hwif_in packing) and is the
        // pattern to follow. Read side is portable as-is; the WRITE side also
        // needs axi_write_engine.o_active_channel_id plumbed out of
        // snk_data_path, which currently ties it off.
        .o_ch_productive    (w_rd_ch_prod),
        .o_ch_backpressure  (w_rd_ch_bp),
        .o_ch_starvation    (w_rd_ch_starv),
        .o_ch_idle          (w_rd_ch_idle),
        .o_ch_overflow      (w_rd_ch_overflow)
    );

    axi_bus_meter #(.NUM_CHANNELS(NC)) u_wr_bus_meter (
        .aclk               (aclk),
        .aresetn            (w_aresetn),
        .i_clear            (w_wr_run && !r_wr_run_d),
        .i_freeze           (~w_wr_run),
        .i_valid            (m_axi_wr_wvalid),
        .i_ready            (m_axi_wr_wready),
        // Channel-id sideband from the sink write engine (RAPIDS TASK-001).
        // o_active_channel_valid is high only while a W burst is in flight, so
        // unattributable cycles increment the aggregate buckets only.
        .i_channel_id       (w_snk_active_ch_id[MCW-1:0]),
        .i_channel_valid    (w_snk_active_ch_valid),
        .o_agg_productive   (w_wr_prod),
        .o_agg_backpressure (w_wr_bp),
        .o_agg_starvation   (w_wr_starv),
        .o_agg_idle         (w_wr_idle),
        .o_ch_productive    (w_wr_ch_prod),
        .o_ch_backpressure  (w_wr_ch_bp),
        .o_ch_starvation    (w_wr_ch_starv),
        .o_ch_idle          (w_wr_ch_idle),
        .o_ch_overflow      (w_wr_ch_overflow)
    );
    /* verilator lint_on PINCONNECTEMPTY */

    // Register read-back. This was `assign hwif_in = '{default: '0}` with the
    // note "status returns are tied off minimally (no fields driven)", so
    // EVERY hardware-driven field in the map read zero in every build and a
    // zero could not be told apart from "this CSR is not wired". STREAM hit
    // exactly this twice (SCHED_ERROR and AXI_{RD,WR}_COMPLETE existed, the
    // core drove the sources, nothing connected them); the shape below is its
    // fix -- default everything, then drive each field from its real source.
    //=========================================================================
    // Tile header status CSRs (TILE_HDR): W1C mirrors of RTL-owned stickies
    //=========================================================================
    // SNK.TILE_STATUS and SRC.TILE_DESC_DROPPED read the stickies below
    // (hw=w, woclr, precedence=sw). A write-1 must clear the RTL bit itself,
    // or the mirror reloads it the next cycle, so the write is decoded here
    // from the register block's own request -- the retro_legacy_blocks
    // pm_acpi_config_regs pattern: mask = wr_data & wr_biten at the
    // register's address, one cycle on the rising edge of the decode
    // (peakrdl_to_cmdrsp holds the request two cycles), set wins in the owner.
    // Offsets: rtl/macro_beats/rapids_engine_regs.rdl (TILE_STATUS 0x2D0,
    // TILE_DESC_DROPPED 0x2D4), SNK half at +0x1000.
    localparam logic [12:0] A_SNK_TILE_STATUS  = 13'h1000 + 13'h2D0;
    localparam logic [12:0] A_SRC_TILE_DROPPED = 13'h0000 + 13'h2D4;
    logic          w_tile_wr_status, w_tile_wr_dropped;
    logic          r_tile_wr_status_d, r_tile_wr_dropped_d;
    logic [31:0]   w_tile_clr_mask;
    logic          w_tile_clr_unsupported, w_tile_clr_tag_mismatch;
    logic [NC-1:0] w_tile_clr_dropped;
    logic          w_tile_adv_done;                    // end-to-end tile credits (TILE_CREDITS)
    logic [rapids_pkg::TILE_NUM_DEST-1:0] w_tile_dest_legal;
    logic          w_tile_resync_busy, w_tile_land_overrun, w_tile_intake_overrun;   // straps
    logic [15:0]   w_tile_ret_count;
    logic [NC-1:0] w_tile_snk_stalled, w_tile_src_stalled;          // stalled-data checks
    logic [`RAPIDS_REGS_NCH-1:0] w_tile_dropped_reg;   // padded to the map for the DROPn glue
    assign w_tile_wr_status  = regblk_req && regblk_req_is_wr && (13'(regblk_addr) == A_SNK_TILE_STATUS);
    assign w_tile_wr_dropped = regblk_req && regblk_req_is_wr && (13'(regblk_addr) == A_SRC_TILE_DROPPED);
    assign w_tile_clr_mask   = 32'(regblk_wr_data & regblk_wr_biten);
    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_tile_wr_status_d  <= 1'b0;
            r_tile_wr_dropped_d <= 1'b0;
        end else begin
            r_tile_wr_status_d  <= w_tile_wr_status;
            r_tile_wr_dropped_d <= w_tile_wr_dropped;
        end
    )
    assign w_tile_clr_unsupported  = w_tile_wr_status && !r_tile_wr_status_d && w_tile_clr_mask[0];
    assign w_tile_clr_tag_mismatch = w_tile_wr_status && !r_tile_wr_status_d && w_tile_clr_mask[1];
    assign w_tile_clr_dropped      = (w_tile_wr_dropped && !r_tile_wr_dropped_d) ? NC'(w_tile_clr_mask) : '0;
    assign w_tile_dropped_reg      = `RAPIDS_REGS_NCH'(sts_tile_desc_dropped);

`include "rapids_g_top_fw.svh"

    always_comb begin
        hwif_in = '{default: '0};

        // Tile header status (zero unless TILE_HDR); SRC DROPn are in the
        // per-variant status include below
        hwif_in.SNK.TILE_STATUS.UNSUPPORTED.next  = sts_tile_unsupported;
        hwif_in.SNK.TILE_STATUS.TAG_MISMATCH.next = sts_tile_tag_mismatch;
        hwif_in.SNK.TILE_COUNTS.DESC_COUNT.next   = sts_tile_desc_count;
        hwif_in.SNK.TILE_COUNTS.CREDIT_COUNT.next = sts_tile_credit_count;
        // End-to-end tile credits (zero unless TILE_CREDITS): SRC half
        hwif_in.SRC.TILE_LEGAL_DEST_LO.LEGAL.next    = w_tile_dest_legal[31:0];
        hwif_in.SRC.TILE_LEGAL_DEST_HI.LEGAL.next    = w_tile_dest_legal[63:32];
        hwif_in.SRC.TILE_CREDIT_STATUS.ADV_DONE.next = w_tile_adv_done;
        hwif_in.SRC.TILE_CREDIT_STATUS.RESYNC_BUSY.next    = w_tile_resync_busy;
        hwif_in.SRC.TILE_CREDIT_STATUS.LAND_OVERRUN.next   = w_tile_land_overrun;
        hwif_in.SRC.TILE_CREDIT_STATUS.INTAKE_OVERRUN.next = w_tile_intake_overrun;
        hwif_in.SRC.TILE_CREDIT_STATUS.RET_COUNT.next      = w_tile_ret_count;
        hwif_in.SRC.TILE_STALLED.CH.next = 16'(w_tile_src_stalled);
        hwif_in.SNK.TILE_STALLED.CH.next = 16'(w_tile_snk_stalled);
        // The build-time straps, for the Hive (0 = no straps)
        hwif_in.SRC.TILE_STRAPS.LAND_FLITS.next    = (TILE_CREDITS != 0) ? 16'(TILE_LAND_FLITS)    : 16'h0;
        hwif_in.SRC.TILE_STRAPS.DESC_PER_CORE.next = (TILE_CREDITS != 0) ? 16'(TILE_DESC_PER_CORE) : 16'h0;
        hwif_in.SNK.TILE_STRAPS.LAND_FLITS.next    = (TILE_CREDITS != 0) ? 16'(TILE_LAND_FLITS)    : 16'h0;
        hwif_in.SNK.TILE_STRAPS.DESC_PER_CORE.next = (TILE_CREDITS != 0) ? 16'(TILE_DESC_PER_CORE) : 16'h0;
        // rapids-g firmware load (src half): FW_WRITABLE, the word at FW_ADDR, the advance
        hwif_in.SRC.FW_CTRL.WRITABLE.next = (FW_WRITABLE != 0);
        hwif_in.SRC.FW_RDATA.DATA.next    = w_src_fw_rd_data;
        hwif_in.SRC.FW_ADDR.ADDR.we       = w_src_fw_adv;
        hwif_in.SRC.FW_ADDR.ADDR.next     = hwif_out.SRC.FW_ADDR.ADDR.value + 16'd1;
        // rapids-g firmware load (snk half): FW_WRITABLE, the word at FW_ADDR, the advance
        hwif_in.SNK.FW_CTRL.WRITABLE.next = (FW_WRITABLE != 0);
        hwif_in.SNK.FW_RDATA.DATA.next    = w_snk_fw_rd_data;
        hwif_in.SNK.FW_ADDR.ADDR.we       = w_snk_fw_adv;
        hwif_in.SNK.FW_ADDR.ADDR.next     = hwif_out.SNK.FW_ADDR.ADDR.value + 16'd1;

        hwif_in.SRC.GLOBAL_STATUS.SYSTEM_IDLE.next   = src_system_idle;
        hwif_in.SRC.DESC_ENGINE_IDLE.DESC_IDLE.next  = `RAPIDS_REGS_NCH'(src_desc_engine_idle);
        hwif_in.SRC.SCHEDULER_IDLE.SCHED_IDLE.next   = `RAPIDS_REGS_NCH'(src_sched_idle);
        hwif_in.SRC.SCHED_ERROR.SCHED_ERR.next       = `RAPIDS_REGS_NCH'(src_sched_error);
        hwif_in.SRC.AXI_RD_COMPLETE.RD_COMPLETE.next = `RAPIDS_REGS_NCH'(src_rd_all_complete);

        hwif_in.SNK.GLOBAL_STATUS.SYSTEM_IDLE.next   = snk_system_idle;
        hwif_in.SNK.DESC_ENGINE_IDLE.DESC_IDLE.next  = `RAPIDS_REGS_NCH'(snk_desc_engine_idle);
        hwif_in.SNK.SCHEDULER_IDLE.SCHED_IDLE.next   = `RAPIDS_REGS_NCH'(snk_sched_idle);
        hwif_in.SNK.SCHED_ERROR.SCHED_ERR.next       = `RAPIDS_REGS_NCH'(snk_sched_error);

        for (int i = 0; i < NC; i++) begin
            hwif_in.SRC.CH_STATE[i].STATE.STATE.next = src_sched_state[i];
            hwif_in.SNK.CH_STATE[i].STATE.STATE.next = snk_sched_state[i];
        end

        // Data-path perf windows, from the two always-on bus meters above.
        hwif_in.SRC.MON.RDMON_PERF_STATUS.WIN_ACTIVE.next  = w_rd_run;
        // LIVE-only, per the register's own description ("reads 0 after
        // close"). The four bucket registers HOLD after close; this one
        // does not, so it is gated by RUN rather than reported stale.
        hwif_in.SRC.MON.RDMON_PERF_WINDOW_CYCLES.VAL.next  =
                                      w_rd_run ? r_rd_win_cycles : 32'd0;
        hwif_in.SRC.MON.RDMON_PERF_PROD_CYCLES.VAL.next    = w_rd_prod;
        hwif_in.SRC.MON.RDMON_PERF_BP_CYCLES.VAL.next      = w_rd_bp;
        hwif_in.SRC.MON.RDMON_PERF_STARV_CYCLES.VAL.next   = w_rd_starv;
        hwif_in.SRC.MON.RDMON_PERF_IDLE_CYCLES.VAL.next    = w_rd_idle;
        hwif_in.SRC.MON.RDMON_PERF_BEAT_COUNT.VAL.next     = r_rd_beats;
        hwif_in.SRC.MON.RDMON_PERF_BYTE_COUNT_LO.VAL.next  = r_rd_bytes[31:0];
        hwif_in.SRC.MON.RDMON_PERF_BYTE_COUNT_HI.VAL.next  = r_rd_bytes[63:32];
        hwif_in.SRC.MON.RDMON_PERF_BURST_COUNT.VAL.next    = r_rd_bursts;

        // Per-channel readout for the channel SRC.PERF_CH_SEL selects. Packed
        // as {bp[31:16], prod[15:0]} and {idle[31:16], starv[15:0]} to match
        // the register descriptions and STREAM's packing. The overflow mask
        // exposes ALL channels at once ({prod,bp,starv,idle} per channel), so
        // it is not selector-indexed.
        hwif_in.SRC.MON.RDMON_PERF_CH_PROD_BP.VAL.next    = {w_rd_sel_bp,   w_rd_sel_prod};
        hwif_in.SRC.MON.RDMON_PERF_CH_STARV_IDLE.VAL.next = {w_rd_sel_idle, w_rd_sel_starv};
        hwif_in.SRC.MON.RDMON_PERF_CH_OVERFLOW.VAL.next   = 32'(w_rd_ch_overflow);

        hwif_in.SNK.MON.WRMON_PERF_STATUS.WIN_ACTIVE.next  = w_wr_run;
        hwif_in.SNK.MON.WRMON_PERF_WINDOW_CYCLES.VAL.next  =
                                      w_wr_run ? r_wr_win_cycles : 32'd0;
        hwif_in.SNK.MON.WRMON_PERF_PROD_CYCLES.VAL.next    = w_wr_prod;
        hwif_in.SNK.MON.WRMON_PERF_BP_CYCLES.VAL.next      = w_wr_bp;
        hwif_in.SNK.MON.WRMON_PERF_STARV_CYCLES.VAL.next   = w_wr_starv;
        hwif_in.SNK.MON.WRMON_PERF_IDLE_CYCLES.VAL.next    = w_wr_idle;
        hwif_in.SNK.MON.WRMON_PERF_BEAT_COUNT.VAL.next     = r_wr_beats;
        hwif_in.SNK.MON.WRMON_PERF_BYTE_COUNT_LO.VAL.next  = r_wr_bytes[31:0];
        hwif_in.SNK.MON.WRMON_PERF_BYTE_COUNT_HI.VAL.next  = r_wr_bytes[63:32];
        hwif_in.SNK.MON.WRMON_PERF_BURST_COUNT.VAL.next    = r_wr_bursts;

        // Per-channel readout for the channel SNK.PERF_CH_SEL selects, packed
        // identically to the read half and to STREAM.
        hwif_in.SNK.MON.WRMON_PERF_CH_PROD_BP.VAL.next    = {w_wr_sel_bp,   w_wr_sel_prod};
        hwif_in.SNK.MON.WRMON_PERF_CH_STARV_IDLE.VAL.next = {w_wr_sel_idle, w_wr_sel_starv};
        hwif_in.SNK.MON.WRMON_PERF_CH_OVERFLOW.VAL.next   = 32'(w_wr_ch_overflow);
        // per-variant fields (16 channels: the overflow masks' channels 8-15)
        `include "rapids_regsel_status.svh"

        // Descriptor-AXI monitor perf window. The monitor computed these all
        // along; nothing collected them, and its window was tied shut
        // (cfg_start/end_trigger were 1'b0) so they never even ran.
        hwif_in.SRC.MON.DAXMON_PERF_STATUS.WIN_ACTIVE.next = src_sts_desc_mon_win_active;
        hwif_in.SRC.MON.DAXMON_PERF_WINDOW_CYCLES.VAL.next = src_sts_desc_mon_win_cycles;
        hwif_in.SRC.MON.DAXMON_PERF_PROD_CYCLES.VAL.next   = src_sts_desc_mon_prod_cycles;
        hwif_in.SRC.MON.DAXMON_PERF_BP_CYCLES.VAL.next     = src_sts_desc_mon_bp_cycles;
        hwif_in.SRC.MON.DAXMON_PERF_STARV_CYCLES.VAL.next  = src_sts_desc_mon_starv_cycles;
        hwif_in.SRC.MON.DAXMON_PERF_IDLE_CYCLES.VAL.next   = src_sts_desc_mon_idle_cycles;
        hwif_in.SRC.MON.DAXMON_PERF_BEAT_COUNT.VAL.next    = src_sts_desc_mon_beat_count;
        hwif_in.SRC.MON.DAXMON_PERF_BYTE_COUNT_LO.VAL.next = src_sts_desc_mon_byte_count[31:0];
        hwif_in.SRC.MON.DAXMON_PERF_BYTE_COUNT_HI.VAL.next = src_sts_desc_mon_byte_count[63:32];
        hwif_in.SRC.MON.DAXMON_PERF_BURST_COUNT.VAL.next   = src_sts_desc_mon_burst_count;

        // Descriptor-AXI monitor perf window. The monitor computed these all
        // along; nothing collected them, and its window was tied shut
        // (cfg_start/end_trigger were 1'b0) so they never even ran.
        hwif_in.SNK.MON.DAXMON_PERF_STATUS.WIN_ACTIVE.next = snk_sts_desc_mon_win_active;
        hwif_in.SNK.MON.DAXMON_PERF_WINDOW_CYCLES.VAL.next = snk_sts_desc_mon_win_cycles;
        hwif_in.SNK.MON.DAXMON_PERF_PROD_CYCLES.VAL.next   = snk_sts_desc_mon_prod_cycles;
        hwif_in.SNK.MON.DAXMON_PERF_BP_CYCLES.VAL.next     = snk_sts_desc_mon_bp_cycles;
        hwif_in.SNK.MON.DAXMON_PERF_STARV_CYCLES.VAL.next  = snk_sts_desc_mon_starv_cycles;
        hwif_in.SNK.MON.DAXMON_PERF_IDLE_CYCLES.VAL.next   = snk_sts_desc_mon_idle_cycles;
        hwif_in.SNK.MON.DAXMON_PERF_BEAT_COUNT.VAL.next    = snk_sts_desc_mon_beat_count;
        hwif_in.SNK.MON.DAXMON_PERF_BYTE_COUNT_LO.VAL.next = snk_sts_desc_mon_byte_count[31:0];
        hwif_in.SNK.MON.DAXMON_PERF_BYTE_COUNT_HI.VAL.next = snk_sts_desc_mon_byte_count[63:32];
        hwif_in.SNK.MON.DAXMON_PERF_BURST_COUNT.VAL.next   = snk_sts_desc_mon_burst_count;

        // Deliberately left at zero, rather than given a plausible driver:
        //  * CHANNEL_IDLE -- the core has no per-channel "channel idle"
        //    source. It reports descriptor-engine idle and scheduler idle
        //    separately, and combining them here would invent a definition
        //    the design does not state.
        //  * SNK AXI_RD_COMPLETE and both AXI_WR_COMPLETE -- the engines do
        //    produce dbg_{rd,wr}_all_complete, but only rapids_src
        //    exports the read one, so no route exists above the engines.
        //  * the MON.* subtree, including every *_PERF_* field: the
        //    descriptor monitor's perf outputs are dangling inside
        //    scheduler_group_array, which has no ports to carry them.
    end

    `RAPIDS_REGS_MOD u_rapids_regs (
        .clk                    (aclk),
        .rst                    (~w_aresetn),  // PeakRDL uses active-high reset
        .s_cpuif_req            (regblk_req),
        .s_cpuif_req_is_wr      (regblk_req_is_wr),
        .s_cpuif_addr           (regblk_addr),  // 13-bit
        .s_cpuif_wr_data        (regblk_wr_data),
        .s_cpuif_wr_biten       (regblk_wr_biten),
        .s_cpuif_req_stall_wr   (regblk_req_stall_wr),
        .s_cpuif_req_stall_rd   (regblk_req_stall_rd),
        .s_cpuif_rd_ack         (regblk_rd_ack),
        .s_cpuif_rd_err         (regblk_rd_err),
        .s_cpuif_rd_data        (regblk_rd_data),
        .s_cpuif_wr_ack         (regblk_wr_ack),
        .s_cpuif_wr_err         (regblk_wr_err),
        .hwif_in                (hwif_in),
        .hwif_out               (hwif_out)
    );

    //=========================================================================
    // Channel kick: staged address + KICK_ENABLE (replaces the address-write kick)
    //=========================================================================
    // Software stages CHx_DESC_ADDR_{LOW,HIGH} per channel and then writes
    // KICK_ENABLE; one 32-bit write launches every selected channel on the
    // same cycle. The old scheme kicked on the ADDRESS WRITE itself, so an
    // N-channel launch cost N APB transactions and the channels started
    // measurably apart.
    //
    // RISING-EDGE detect on the kick, NOT the level. peakrdl_to_cmdrsp holds
    // regblk_req across CMD_IDLE -> CMD_WAIT_ACK, and a PeakRDL singlepulse
    // fires once per decoded write strobe, so a held request pulses KICKn on
    // consecutive cycles -- launching the channel TWICE and moving exactly 2x
    // the descriptor's beats. STREAM hit precisely this; edge-detecting makes
    // the launch independent of how long the adapter holds the request.
    //
    // The request is then HELD until the descriptor engine accepts it, so a
    // one-cycle pulse cannot be lost while a channel is briefly unready. That
    // is the one behavioural change from the old kick block, whose HIGH write stalled
    // the APB until the engine accepted: acceptance is now asynchronous to the
    // bus write, so a completed write no longer means "accepted".
    //=========================================================================
    localparam int RNC = `RAPIDS_REGS_NCH;         // channels in the register map
    logic [RNC-1:0]       w_kick_src_pulse, w_kick_snk_pulse;
    logic [RNC-1:0]       r_kick_src_d,     r_kick_snk_d;
    logic [RNC-1:0]       w_kick_src_edge,  w_kick_snk_edge;
    logic [RNC-1:0][63:0] w_staged_src_addr, w_staged_snk_addr;

    // KICKn and CHn_DESC_ADDR_* exist per channel by NAME, so their glue
    // comes with the register-map variant
    always_comb begin
        `include "rapids_regsel_kick.svh"
    end

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_kick_src_d <= '0;
            r_kick_snk_d <= '0;
        end else begin
            r_kick_src_d <= w_kick_src_pulse;
            r_kick_snk_d <= w_kick_snk_pulse;
        end
    )
    assign w_kick_src_edge = w_kick_src_pulse & ~r_kick_src_d;
    assign w_kick_snk_edge = w_kick_snk_pulse & ~r_kick_snk_d;

    logic [NC-1:0]          r_kick_src_pending, r_kick_snk_pending;
    logic [NC-1:0][AW-1:0]  r_kick_src_addr,    r_kick_snk_addr;

    `ALWAYS_FF_RST(aclk, w_aresetn,
        if (`RST_ASSERTED(w_aresetn)) begin
            r_kick_src_pending <= '0;
            r_kick_snk_pending <= '0;
            r_kick_src_addr    <= '{default:'0};
            r_kick_snk_addr    <= '{default:'0};
        end else begin
            for (int ch = 0; ch < NC; ch++) begin
                if (w_kick_src_edge[ch]) begin
                    r_kick_src_pending[ch] <= 1'b1;
                    r_kick_src_addr[ch]    <= AW'(w_staged_src_addr[ch]);
                end else if (r_kick_src_pending[ch] && src_apb_ready[ch]) begin
                    r_kick_src_pending[ch] <= 1'b0;
                end

                if (w_kick_snk_edge[ch]) begin
                    r_kick_snk_pending[ch] <= 1'b1;
                    r_kick_snk_addr[ch]    <= AW'(w_staged_snk_addr[ch]);
                end else if (r_kick_snk_pending[ch] && snk_apb_ready[ch]) begin
                    r_kick_snk_pending[ch] <= 1'b0;
                end
            end
        end
    )

    always_comb begin
        for (int ch = 0; ch < NC; ch++) begin
            src_apb_valid[ch] = r_kick_src_pending[ch];
            src_apb_addr [ch] = r_kick_src_addr[ch];
            snk_apb_valid[ch] = r_kick_snk_pending[ch];
            snk_apb_addr [ch] = r_kick_snk_addr[ch];
        end
    end


    //=========================================================================
    // Configuration for the SOURCE half (u_cfg_src <- hwif_out.SRC.*)
    //=========================================================================
    logic [NC-1:0]  src_cfg_channel_enable;
    logic [NC-1:0]  src_cfg_channel_reset;
    logic           src_cfg_sched_enable;
    logic [31:0]    src_cfg_sched_timeout_cycles;
    logic [7:0]     src_cfg_sched_timeout_limit;
    logic           src_cfg_sched_timeout_enable;
    logic           src_cfg_sched_err_enable;
    logic           src_cfg_sched_compl_enable;
    logic           src_cfg_sched_perf_enable;
    logic           src_cfg_desceng_enable;
    logic           src_cfg_desceng_prefetch;
    logic [3:0]     src_cfg_desceng_fifo_thresh;
    logic [8:0]     src_cfg_ctrlrd_max_try;
    logic [AW-1:0]  src_cfg_desceng_addr0_base;
    logic [AW-1:0]  src_cfg_desceng_addr0_limit;
    logic [AW-1:0]  src_cfg_desceng_addr1_base;
    logic [AW-1:0]  src_cfg_desceng_addr1_limit;
    logic           src_cfg_desc_mon_enable;
    logic           src_cfg_desc_mon_err_enable;
    logic           src_cfg_desc_mon_perf_enable;
    logic           src_cfg_desc_mon_timeout_enable;
    logic [31:0]    src_cfg_desc_mon_timeout_cycles;
    logic [31:0]    src_cfg_desc_mon_latency_thresh;
    logic [15:0]    src_cfg_desc_mon_pkt_mask;
    logic [3:0]     src_cfg_desc_mon_err_select;
    logic [7:0]     src_cfg_desc_mon_err_mask;
    logic [7:0]     src_cfg_desc_mon_timeout_mask;
    logic [7:0]     src_cfg_desc_mon_compl_mask;
    logic [7:0]     src_cfg_desc_mon_thresh_mask;
    logic [7:0]     src_cfg_desc_mon_perf_mask;
    logic [7:0]     src_cfg_desc_mon_addr_mask;
    logic [7:0]     src_cfg_desc_mon_debug_mask;
    // SRC.MON.RDMON_* -> source-egress AXIS monitor-lite (rapids TASK-015)
    logic         src_cfg_rdeng_mon_enable;
    logic         src_cfg_rdeng_mon_err_enable;
    logic         src_cfg_rdeng_mon_compl_enable;
    logic         src_cfg_rdeng_mon_perf_enable;
    logic         src_cfg_rdeng_mon_timeout_enable;
    logic [31:0]  src_cfg_rdeng_mon_timeout_cycles;
    logic [31:0]  src_cfg_rdeng_mon_latency_thresh;
    logic [15:0]  src_cfg_rdeng_mon_pkt_mask;
    logic [7:0]     src_cfg_axi_rd_xfer_beats;  // used by source half
    logic [7:0]     src_cfg_drain_size;         // used by source half

    //=========================================================================
    // Configuration for the SINK half (u_cfg_snk <- hwif_out.SNK.*)
    //=========================================================================
    logic [NC-1:0]  snk_cfg_channel_enable;
    logic [NC-1:0]  snk_cfg_channel_reset;
    logic           snk_cfg_sched_enable;
    logic [31:0]    snk_cfg_sched_timeout_cycles;
    logic [7:0]     snk_cfg_sched_timeout_limit;
    logic           snk_cfg_sched_timeout_enable;
    logic           snk_cfg_sched_err_enable;
    logic           snk_cfg_sched_compl_enable;
    logic           snk_cfg_sched_perf_enable;
    logic           snk_cfg_desceng_enable;
    logic           snk_cfg_desceng_prefetch;
    logic [3:0]     snk_cfg_desceng_fifo_thresh;
    logic [8:0]     snk_cfg_ctrlrd_max_try;
